import math

def get_factors(n):
    """
    Returns (a, b) such that n = 2^a * 5^b, or None if n is not of this form.
    Assumes n >= 1.
    """
    if n <= 0:
        return None

    a = 0
    temp_n = n
    while temp_n > 0 and temp_n % 2 == 0:
        a += 1
        temp_n //= 2

    b = 0
    while temp_n > 0 and temp_n % 5 == 0:
        b += 1
        temp_n //= 5

    if temp_n == 1:
        return (a, b)
    else:
        return None

def find_solutions():
    solutions = []

    # Iterate N from 0 to 1000. We handle negative N by symmetry later.
    for N in range(0, 1001):
        X = N**2 - 625

        if X < 1:
            continue

        factors = get_factors(X)

        if factors:
            a, b = factors

            # Found a solution for positive N
            solutions.append((a, b, N))

            # Found a solution for negative N (if N != 0)
            if N != 0:
                solutions.append((a, b, -N))

    return solutions

solutions = find_solutions()
print(f"Found {len(solutions)} integer triples.")
for sol in solutions:
    print(sol)
